def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    decrease = v2 - v1
    return {
        "value": decrease,
        "trace": {
            "v1": v1,
            "v2": v2,
            "decrease": decrease,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": "monetary"
            }
        }
    }
